window.FILM_WORK_PROMPTS={"work_id":"src-74e80149cf5367d0","records":[{"work_id":"src-74e80149cf5367d0","frame_id":"FG-1b9e773c1e4b287b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/075.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"一名身穿浅色宇航服的人物坐在狭窄的舱室内，头戴透明面罩头盔，面部正对镜头，背景为深灰色的舱壁结构。","analysis":"画面采用居中构图，人物头部与肩部占据画面中心约二分之一区域。视角为平视，人物面部可见，身体仅显示至肩部。环境光线昏暗，主要光源来自人物面部前方，照亮头盔面罩与面部，形成高光反射，周围舱壁处于阴影中，整体色调偏冷灰。","prompt":"低分辨率画面，一名身穿米白色宇航服的人物坐在狭窄的深灰色舱室内，头戴带有透明面罩的球形头盔，面罩上有明显的反光。人物面部正对镜头，表情严肃，仅头部和肩部可见。背景是模糊的深色舱壁，带有矩形面板结构，整体光线昏暗，面部受光，周围处于阴影中，色调冷峻。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:05:36-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/075.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-8606082bf3404a4a","origin":"visual"},{"work_id":"src-74e80149cf5367d0","frame_id":"FG-4d4321651b37672f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/205.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"昏暗室内，左侧大面积红褐色蓬松毛发占据主体，右侧可见人物面部及金属环状结构，背景为斑驳墙面。","analysis":"画面采用侧向构图，左侧红褐色毛发体积庞大，遮挡了大部分空间。右侧人物面部仅露出局部，被金属环状物环绕。整体光线极暗，呈低照度状态，光源似乎来自右侧，在面部和金属结构上形成微弱高光，其余部分隐没在阴影中，色彩以暗褐与灰绿为主。","prompt":"昏暗低照度室内场景，画面左侧被一大团红褐色蓬松毛发占据，质感粗糙且体积庞大，几乎填满左半部分空间。右侧可见一名人物面部，肤色苍白，眼神直视前方，头部周围环绕着金属质感的环状结构，下方有模糊的浅色物体。背景是斑驳的灰绿色墙面，带有模糊的纹理。整体色调阴郁，以暗褐色和灰绿色为主，光线微弱且集中在右侧面部，营造出压抑、神秘的视觉氛围，画面颗粒感明显。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:05:42-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/205.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-ca1012234fd607cd","origin":"visual"},{"work_id":"src-74e80149cf5367d0","frame_id":"FG-150e3dfb6a5be890","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/335.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"画面主体为一只大猩猩的头部与肩部，占据右侧大部分空间。背景昏暗模糊，左后方隐约可见一个站立的人形轮廓，环境光线微弱，整体氛围压抑。","analysis":"构图采用非对称布局，主体位于右侧，面部细节在低分辨率下呈现为深色块面与粗糙纹理。人物仅头部及肩部可见，占据画面约三分之二。视角接近平视，光线从上方投射，在面部形成明暗对比，色调偏暖褐与深灰，背景虚化严重，仅能辨识模糊的人形色块。","prompt":"低分辨率画面，右侧前景是一只大猩猩的头部与肩部特写，毛发呈现深褐色粗糙质感，面部处于阴影中，轮廓模糊。背景昏暗且严重虚化，左后方隐约可见一个站立的人形轮廓，呈暗红色调。整体光线微弱，色调偏暖褐与深灰，营造出压抑、神秘的氛围。画面焦点集中在大猩猩的面部区域，但细节因分辨率低而不可辨，仅保留大致的明暗块面与空间层次。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:05:48-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/335.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-9dad767e96b3390b","origin":"visual"},{"work_id":"src-74e80149cf5367d0","frame_id":"FG-c440011683aeb01f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/464.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"昏暗的岩石环境中，一大群人站立聚集。前景人物密集，背景人影延伸至高处，整体呈现冷色调的群像。","analysis":"画面采用低角度仰拍，前景人物占据画面下半部，可见上半身或全身轮廓，背景人物随距离变小。环境由深色岩石构成，占据上方及两侧空间。光线极暗，整体笼罩在冷蓝色调中，人物面部与衣物细节模糊，仅能辨识大致轮廓与明暗层次。","prompt":"昏暗岩石环境中的大群人物站立聚集，低角度仰拍视角。前景人物密集，可见上半身或全身轮廓，背景人影延伸至高处岩石。整体笼罩在冷蓝色调中，光线极暗，人物面部与衣物细节模糊，仅能辨识大致轮廓与明暗层次。环境由深色岩石构成，占据上方及两侧空间，人物与岩石比例协调，呈现压抑的群像氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:05:57-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/464.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-b6f68059f9572603","origin":"visual"},{"work_id":"src-74e80149cf5367d0","frame_id":"FG-fd11dcf7cf55307b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/593.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"一只黑毛猿猴头部位于白色宇航服头盔内，面部正对镜头。背景为米色座椅靠背与舱壁结构，环境紧凑，主体占据画面中心大部分区域。","analysis":"构图以猿猴面部为绝对中心，头盔边缘形成圆形框架。画面仅可见头部及肩部上沿，身体其余部分不可见。视角平视，光线柔和均匀，面部处于头盔内部阴影中，与外部明亮白色衣物形成明暗对比。色彩以白色、米色和深褐色为主，层次分明。","prompt":"一只黑毛猿猴头部位于白色宇航服头盔内，面部正对镜头，眼神平静。头盔边缘为厚实的白色织物结构，包裹住头部。猿猴面部处于头盔内部阴影中，与外部明亮白色衣物形成明暗对比。背景左侧可见米色座椅靠背，右侧为深色舱壁结构，环境紧凑。画面仅可见头部及肩部上沿，身体其余部分不可见。视角平视，光线柔和均匀，色彩以白色、米色和深褐色为主，层次分明。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:06:03-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/593.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-22d9343b98d4a324","origin":"visual"},{"work_id":"src-74e80149cf5367d0","frame_id":"FG-0a0f6c0ebb30ae8c","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/085.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"一名短发男子位于画面右侧，身体背向镜头并向左后方回头，面部朝向左侧。背景为大面积模糊的深绿色植被，环境光线昏暗，人物占据画面右半部分。","analysis":"构图将人物置于右侧，左侧留出空间展示模糊背景。人物头部及肩背部可见，身体呈扭转姿态。光线从左侧照射，照亮人物面部左侧及颈部，右侧面部及背部处于阴影中。背景为失焦的绿色色块，与人物形成虚实对比。整体色调偏暗，以绿色和肤色为主，明暗对比集中在人物面部轮廓上。","prompt":"低分辨率画面，右侧前景为一名短发男子，身穿土黄色或卡其色衣物，身体背对镜头并向左后方回头，面部朝向左侧。人物面部及颈部可见，皮肤上有汗渍或水珠反光，神情紧绷。背景为大面积失焦的深绿色植被，形成模糊的色块。光线昏暗，主要光源来自左侧，照亮人物面部左侧，右侧面部及背部处于阴影中。整体色调偏暗，绿色背景与人物肤色形成对比，画面具有电影质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:08:05+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/085.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-0f9cc3b7d62d499e","origin":"visual"},{"work_id":"src-74e80149cf5367d0","frame_id":"FG-934f4c8b77657480","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/215.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"昏暗的洞穴或地下空间内，数十名人物剪影分列左右两侧站立，中央通道尽头有一人站立，背景为巨大的岩石壁面与拱形结构。","analysis":"画面采用对称式构图，中央通道形成视觉引导线。前景人物仅可见上半身或全身剪影，因背光而细节模糊，远处人物相对较小。视角接近平视，整体处于极暗环境，仅左侧有一处明亮的橙红色光源，其余区域由微弱的暖色光点点缀，明暗对比强烈，营造出压抑神秘的氛围。","prompt":"昏暗的地下洞穴场景，低分辨率画面。数十名人物剪影分列画面左右两侧，呈站立姿态，身体轮廓模糊，仅能辨识大致身形。中央是一条向深处延伸的通道，尽头处有一人站立，身形较小。背景是巨大的岩石壁面，上方有拱形结构。左侧前景有一处明亮的橙红色光源，照亮了附近人物的边缘，其余区域光线极暗，仅有零星微弱光点。整体色调深沉，以黑色和深褐色为主，明暗对比强烈，营造出压抑、神秘且庄重的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:08:11+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/215.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-13acd4487784e658","origin":"visual"},{"work_id":"src-74e80149cf5367d0","frame_id":"FG-d66281ed9fa79309","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/345.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"夜色中，巨大的深色山体占据背景，山脊处爆发出一团刺眼的红白色强光，上方升起一缕烟雾。前景下方排列着数个尖顶帐篷的剪影，整体环境昏暗压抑。","analysis":"画面采用低角度仰视构图，巨大的山体轮廓在黑暗中形成压迫感。前景的帐篷群呈黑色剪影状，仅露出尖顶轮廓，与背景山体形成大小对比。视觉中心位于山体中部的爆炸亮斑，红白光芒向四周发散出明显的十字星芒，照亮了周围的烟雾。整体色调极暗，仅靠中心光源提供照明，明暗对比强烈。","prompt":"这是一张低分辨率的夜间场景画面。背景是一座巨大的深色山体，轮廓在黑暗中隐约可见。在山体中部的山脊位置，爆发出一团强烈的红白色亮光，光芒呈十字星芒状向四周散射，亮斑上方升起一股灰白色的烟雾。画面前景下方排列着一排尖顶帐篷的黑色剪影，帐篷呈三角形，密集分布。整体环境极度昏暗，除了中心的爆炸亮光和烟雾外，其余部分几乎淹没在黑暗中，呈现出一种紧张、神秘的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:08:17+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/345.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-eeb837b1048ce5fc","origin":"visual"},{"work_id":"src-74e80149cf5367d0","frame_id":"FG-d7e4fa10c0f9a095","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/474.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"昏暗的蓝灰色天空下，约十名身着粗糙兽皮或深色衣物的人物聚集站立。他们身形高大，部分人手持长矛，整体呈现出一种原始部落集结的静态场面。","analysis":"画面采用低角度仰拍，突显了人物的压迫感与高大轮廓。人物主要呈现上半身及头部，身体下部被画面边缘截断。整体光线极暗，呈冷调蓝灰色，人物面部与身体细节模糊，仅能辨识出深色毛发、粗糙衣物纹理及竖立的长矛轮廓，明暗对比微弱，营造出压抑、神秘的视觉氛围。","prompt":"这是一张低分辨率的昏暗画面，背景是均匀的蓝灰色天空。画面中聚集着约十名原始部落风格的人物，采用仰视视角拍摄。人物身穿深色、粗糙的兽皮或编织衣物，留着长发和胡须，轮廓在暗光中显得模糊。画面中央及右侧的人物手中竖立着细长的长矛，矛尖指向天空。人物呈站立姿态，密集地排列在一起，占据了画面的大部分空间。整体色调阴冷，光线微弱，没有明显的高光，人物面部细节不可辨，仅能看清大致的头部形状和身体轮廓，呈现出一种原始、肃穆且压抑的群像视觉效果。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:08:24+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/474.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-a5430685ecf6f1fc","origin":"visual"},{"work_id":"src-74e80149cf5367d0","frame_id":"FG-fc2d2b1ca2417874","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/603.jpg","source_page":"https://film-grab.com/2016/05/17/planet-of-the-apes/","scene":"画面中央站立着一名戴金属头盔的深色皮肤人物，面部有胡须，身穿厚重铠甲。其左右两侧各有一名戴红褐色尖顶头盔的人物，背景是灰白色的朦胧远景。","analysis":"构图呈中心对称，主体人物占据画面中心，左右两侧人物形成护卫态势。人物上半身可见，头部至胸部清晰，肩部有圆形金属护甲。视角平视，光线柔和漫射，整体色调偏灰黄，金属头盔与红褐色头盔形成材质对比，背景虚化，主体轮廓分明。","prompt":"低分辨率画面，中央站立一名深色皮肤人物，戴银灰色金属头盔，面部有深色胡须，身穿深色铠甲，肩部有圆形金属护甲。左右两侧各有一名戴红褐色尖顶头盔的人物，头盔呈圆锥形，面部被阴影遮挡。背景为灰白色朦胧环境，远处有模糊的尖刺状结构。光线柔和，整体色调偏黄灰，金属质感与皮革质感对比明显，人物上半身清晰，远景虚化。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:08:29+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/603.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-346f492d904653e6","origin":"visual"}]};